   144→      BaseOptions(
   145→        baseUrl: _baseUrl,
   146→        connectTimeout: const Duration(seconds: 10),
   147→        receiveTimeout: const Duration(seconds: 10),
   148→        sendTimeout: const Duration(seconds: 10),
   149→        contentType: 'application/json',
   150→      ),
   151→    );
   152→
   153→    // 요청 로깅 인터셉터
